package com.aetherforge.api;import com.aetherforge.repo.MachineRepository;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/v1/machines") public class MachineController {private final MachineRepository repo;public MachineController(MachineRepository r){repo=r;}@GetMapping List<Map<String,Object>> list(@RequestParam(required=false)String q,@RequestParam(required=false)String status){return repo.list(q,status);}@GetMapping("/{id}") Map<String,Object> one(@PathVariable String id){return repo.one(id);}@GetMapping("/{id}/sensors") List<Map<String,Object>> sensors(@PathVariable String id,@RequestParam(defaultValue="60")int minutes){return repo.sensors(id,minutes);}}
